import { describe, it, expect } from 'vitest'
import {
  applyDefense,
  calcMonsterDamage,
  calcPlayerHitChance,
  calcMonsterHitChance,
  monsterEvasion,
  getPrimaryStat,
  calcPlayerDamage,
  rollDrops,
  refreshStamina,
  hpBar,
  progressBar,
} from '../src/engine/combat'
import { mulberry32 } from '../src/engine/rng'

// Parity fixtures generated by RUNNING the bot's lib/combat-engine.js.

describe('applyDefense (bot parity)', () => {
  it.each([
    [100, 0, 100],
    [100, 500, 50],      // 500 def = exactly 50% mitigation
    [100, 10000, 4],     // soft curve, never zero
    [1, 999999, 1],      // 97% cap keeps a floor of 1
    [0, 100, 1],         // floor of 1 even from 0 raw
    [55.7, 123, 44],
  ])('raw %f vs def %f → %i', (raw, def, expected) => {
    expect(applyDefense(raw, def)).toBe(expected)
  })
})

describe('calcMonsterDamage (bot parity)', () => {
  // rng = 0.5 → variance exactly 1.0 (0.80 + 0.5×0.40)
  const rng = () => 0.5

  it('no defend: 100 atk vs 500 def → 50', () => {
    expect(calcMonsterDamage(100, 500, false, rng)).toBe(50)
  })

  it('defending doubles DEF: → 33', () => {
    expect(calcMonsterDamage(100, 500, true, rng)).toBe(33)
  })

  it('zero def takes full damage', () => {
    expect(calcMonsterDamage(100, 0, false, rng)).toBe(100)
  })

  it('variance spans 0.80–1.20', () => {
    expect(calcMonsterDamage(100, 0, false, () => 0)).toBe(80)
    expect(calcMonsterDamage(100, 0, false, () => 0.999999)).toBe(119)
  })

  it('NaN inputs never produce NaN damage', () => {
    const d = calcMonsterDamage(NaN, undefined as unknown as number, false, rng)
    expect(Number.isFinite(d)).toBe(true)
    expect(d).toBeGreaterThanOrEqual(1)
  })
})

describe('hit chances (bot parity)', () => {
  const rogue50 = { classId: 'rogue', stats: { str: 1, agi: 50, int: 1, def: 1, lck: 1 } }
  const warrior5 = { classId: 'warrior', stats: { str: 1, agi: 5, int: 1, def: 1, lck: 1 } }

  it('player vs regular: 0.90 + agi×0.0015 − 0.05', () => {
    expect(calcPlayerHitChance(rogue50, { tier: 'regular' })).toBeCloseTo(0.925, 10)
  })

  it('player vs boss: boss evasion is only 0.02', () => {
    expect(calcPlayerHitChance(warrior5, { isBoss: true })).toBeCloseTo(0.8875, 10)
  })

  it('player vs elite: 0.10 evasion', () => {
    expect(calcPlayerHitChance(rogue50, { tier: 'elite' })).toBeCloseTo(0.875, 10)
  })

  it('clamps to [0.60, 0.99]', () => {
    const slow = { classId: 'warrior', stats: { str: 1, agi: 0, int: 1, def: 1, lck: 1 } }
    expect(calcPlayerHitChance(slow, { evasion: 0.99 })).toBe(0.60)
    const fast = { classId: 'rogue', stats: { str: 1, agi: 100000, int: 1, def: 1, lck: 1 } }
    expect(calcPlayerHitChance(fast, {})).toBe(0.99)
  })

  it('monster vs player (bot fixtures)', () => {
    expect(calcMonsterHitChance({ tier: 'regular' }, rogue50)).toBeCloseTo(0.92, 10)
    expect(calcMonsterHitChance({ isBoss: true }, warrior5)).toBe(0.99) // clamped
  })

  it('evasion by tier with explicit override (bot fixtures)', () => {
    expect(monsterEvasion({ tier: 'regular' })).toBe(0.05)
    expect(monsterEvasion({ tier: 'elite' })).toBe(0.10)
    expect(monsterEvasion({ isBoss: true })).toBe(0.02)
    expect(monsterEvasion({})).toBe(0.05)
    expect(monsterEvasion({ tier: 'regular', evasion: 0.5 })).toBe(0.5)
    expect(monsterEvasion({ tier: 'regular', evasion: 5 })).toBe(0.75) // MAX_EVASION
  })
})

describe('calcPlayerDamage', () => {
  const player = {
    classId: 'mage',
    stats: { str: 2, agi: 8, int: 32, def: 1, lck: 100 }, // lck 100 → crit 25%
  }

  it('reads skill power from effects[0].multiplier (the corrected read)', () => {
    const skill = { effects: [{ type: 'attack', multiplier: 1.33 }] }
    const { rawDmg, isCrit, critMult } = calcPlayerDamage(player, skill, 1, 0, () => 1) // never crit
    expect(isCrit).toBe(false)
    expect(critMult).toBe(1)
    expect(rawDmg).toBe(Math.floor(32 * 1.33)) // 42
  })

  it('falls back to 1.0 when no multiplier exists (basic attack)', () => {
    const { rawDmg } = calcPlayerDamage(player, null, 1, 0, () => 1)
    expect(rawDmg).toBe(32)
  })

  it('crit multiplies by 1.5', () => {
    const skill = { effects: [{ type: 'attack', multiplier: 2 }] }
    const { rawDmg, isCrit, critMult } = calcPlayerDamage(player, skill, 1, 0, () => 0) // always crit
    expect(isCrit).toBe(true)
    expect(critMult).toBe(1.5)
    expect(rawDmg).toBe(Math.floor(32 * 2 * 1.5)) // 96
  })

  it('uses the class primary stat (mage → int)', () => {
    expect(getPrimaryStat(player)).toBe(32)
    expect(getPrimaryStat({ classId: 'rogue', stats: { str: 9, agi: 77, int: 1, def: 1, lck: 1 } })).toBe(77)
  })

  it('crit chance caps at 95%', () => {
    const lucky = { classId: 'mage', stats: { str: 1, agi: 1, int: 1, def: 1, lck: 10000 } }
    // lck 10000 × 0.002 = 20 → capped to 0.95; rng 0.9499 < 0.95 → crit
    const { isCrit } = calcPlayerDamage(lucky, null, 1, 0, () => 0.9499)
    expect(isCrit).toBe(true)
    const { isCrit: miss } = calcPlayerDamage(lucky, null, 1, 0, () => 0.951)
    expect(miss).toBe(false)
  })
})

describe('rollDrops', () => {
  it('drops entries whose roll passes, never zero-chance placeholders', () => {
    const drops = [
      { itemId: 'a', chance: 1.0 },
      { itemId: 'b', chance: 0 },
      { itemId: 'c', chance: 0.5 },
    ]
    expect(rollDrops(drops, () => 0.4)).toEqual(['a', 'c'])
    expect(rollDrops(drops, () => 0.6)).toEqual(['a'])
  })
})

describe('refreshStamina (bot parity)', () => {
  it('refills to max when past resetAt, rolling resetAt to next midnight', () => {
    const now = new Date('2026-11-25T12:00:00').getTime()
    const stale = { current: 3, max: 30, resetAt: now - 1000 }
    const fresh = refreshStamina(stale, now)
    expect(fresh.current).toBe(30)
    expect(fresh.max).toBe(30)
    expect(fresh.resetAt).toBeGreaterThan(now)
  })

  it('keeps an unexpired stamina untouched', () => {
    const now = new Date('2026-11-25T12:00:00').getTime()
    const live = { current: 12, max: 30, resetAt: now + 60_000 }
    expect(refreshStamina(live, now)).toBe(live)
  })
})

describe('display bars (bot parity)', () => {
  it.each([
    [5, 10, '[█████░░░░░] 5/10'],
    [0, 10, '[░░░░░░░░░░] 0/10'],
    [50, 10, '[██████████] 50/10'], // over-max clamps
    [NaN, 10, '[░░░░░░░░░░] 0/10'],  // NaN never renders
  ])('hpBar(%s, %s)', (cur, max, expected) => {
    expect(hpBar(cur, max)).toBe(expected)
  })

  it('progressBar clamps to [0,1]', () => {
    expect(progressBar(0.5)).toBe('[█████░░░░░]')
    expect(progressBar(-1)).toBe('[░░░░░░░░░░]')
    expect(progressBar(2)).toBe('[██████████]')
  })
})

describe('mulberry32 rng', () => {
  it('is deterministic for a seed and spans [0,1)', () => {
    const a = mulberry32(42)
    const b = mulberry32(42)
    const seqA = [a(), a(), a()]
    const seqB = [b(), b(), b()]
    expect(seqA).toEqual(seqB)
    for (const v of seqA) {
      expect(v).toBeGreaterThanOrEqual(0)
      expect(v).toBeLessThan(1)
    }
  })
})
